import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {binding,bindingPath,controls,surveyExperiencePlan,surveyExperienceOutputs} from './survey-experience-scope.mjs';
import {decodeLocal} from './survey-experience-candidate.mjs';
import {requiredChecks,failedChecks} from './merge-gate.mjs';
const head='a'.repeat(40),env={CI_EVENT:'pull_request',CI_HEAD_REF:'work/survey-experience-20261022'};
const entries=Object.entries(binding.source).map(([file,b])=>({file,status:b.before?'M':'A',oldMode:b.before?'100644':'000000',newMode:'100644'}));entries.push({file:bindingPath,status:'A',oldMode:'000000',newMode:'100644'});
function read(cmd,key){assert.equal(cmd,'rev-parse');const [ref,...p]=key.split(':');const file=p.join(':');if(file==='server-version/frontend')return binding.frontendTree;if(binding.dependencyInputs[file])return binding.dependencyInputs[file];return binding.source[file]?.[ref===binding.base?'before':'after'];}
const plan=()=>surveyExperiencePlan(entries,binding.base,head,read,env);
test('exact source candidate produces only frontend bounded route',()=>{const p=plan(),o=surveyExperienceOutputs(p);assert.equal(p.route,'survey-experience');assert.equal(o.codeql,true);for(const k of ['frontend','frontend_build','scale','cognitive','situational','maintenance'])assert.equal(o[k],false);});
test('unknown source, renamed/deleted/mode drift fail closed',()=>{for(const e of [{file:'server-version/backend/new.ts',status:'A',oldMode:'000000',newMode:'100644'},{...entries[0],status:'D',newMode:'000000'},{...entries[0],newMode:'120000'}])assert.throws(()=>surveyExperiencePlan([...entries,e],binding.base,head,read,env));});
test('base branch full manual and product drift rejected',()=>{assert.throws(()=>surveyExperiencePlan(entries,'b'.repeat(40),head,read,env));for(const patch of [{CI_HEAD_REF:'other'},{CI_FORCE_FULL:'true'},{CI_EVENT:'workflow_dispatch'}])assert.throws(()=>surveyExperiencePlan(entries,binding.base,head,read,{...env,...patch}));assert.throws(()=>surveyExperiencePlan(entries,binding.base,head,()=> 'wrong',env));});
test('frontend transitive inputs and external fixtures cannot drift',()=>{for(const target of ['server-version/frontend',...Object.keys(binding.dependencyInputs)])assert.throws(()=>surveyExperiencePlan(entries,binding.base,head,(cmd,key)=>key.endsWith(':'+target)?'changed':read(cmd,key),env));});
test('original reports retain failures and accept exact 162 plus 19 only',()=>{const a=decodeLocal(readFileSync('.github/scripts/survey-experience-local.json'));assert.equal(a.newPassed,162);assert.equal(a.priorApplicablePassed,19);assert.equal(a.ciExecuted,false);assert.equal(a.signed,false);assert.throws(()=>decodeLocal(Buffer.from('{}')));});
test('stable gate requires scope frontend qualification and CodeQL success',()=>{const outputs=Object.fromEntries(Object.entries(surveyExperienceOutputs(plan())).map(([k,v])=>[k,String(v)]));const needs={scope:{outputs,result:'success'},'survey-experience':{result:'success'},codeql:{result:'success'}};assert.deepEqual(requiredChecks(needs,false),['scope','survey-experience','codeql']);assert.deepEqual(failedChecks(needs,false),[]);needs['survey-experience'].result='skipped';assert.ok(failedChecks(needs,false).includes('survey-experience'));assert.ok(failedChecks(needs,true).includes('scope'));});
test('workflow performs no repeated app qualification or backend execution',()=>{const s=readFileSync('.github/workflows/ci-survey-experience.yml','utf8');assert.doesNotMatch(s,/vitest|tsc |eslint|postgres|restore|ci-training/);for(const mode of ['admit','build','audit','browser-report'])assert.equal(s.split('survey-experience-candidate.mjs '+mode).length-1,1);assert.match(s,/trivy image --exit-code 1/);assert.match(s,/survey-experience-images/);assert.match(s,/survey-experience-browser.cjs/);});
test('old routes not reclassified without this candidate marker',()=>{assert.equal(surveyExperiencePlan([{file:'README.md'}],binding.base,head,read,env),null);assert.ok(controls.includes('.github/scripts/content-scope.mjs'));});

test('PR merge tree must equal exact proposed source tree',()=>{assert.throws(()=>surveyExperiencePlan(entries,binding.base,head,(cmd,key)=>key.endsWith('^{tree}')?(key.startsWith(head)?'merge-tree':'source-tree'):read(cmd,key),{...env,CI_SOURCE_HEAD:'c'.repeat(40)}));});
